+// could never observe the load it demands (#1735). The set is session-wide, so
+// one agent's load answers for another's edit — which is what a session-scoped
+// gate means, and the side to err on for a gate that otherwise cannot pass.
+export function sessionSkillLoads(transcriptPath) {
+  const names = [];
+  for (const path of sessionTranscriptPaths(transcriptPath)) {
+    // A stream being written as we read it costs its loads, never the others'.
+    try { names.push(...skillLoads(parseEntries(readFileSync(path, 'utf8')))); } catch { /* unreadable */ }
+  }
