12	export function parseEntries(text) {
13	  const entries = [];
14	  for (const line of (text || '').split('\n')) {
15	    if (!line.trim()) continue;
16	    try { entries.push(JSON.parse(line)); } catch { /* partial trailing write — skip the line */ }
17	  }
18	  return entries;
19	}
20	
21	function humanText(entry) {
22	  if (entry.type !== 'user' || entry.isMeta || entry.isSidechain) return null;
23	  const content = entry.message?.content;
24	  const text = typeof content === 'string'
25	    ? content
26	    : Array.isArray(content) && content.length && content.every((c) => c?.type === 'text')
27	      ? content.map((c) => c.text).join('\n')
28	      : null;
29	  if (!text || text.trimStart().startsWith('<')) return null;
30	  return text;
31	}
32	
33	// The owner's own turns, in order: [{ index, timestamp, text }].
34	export function humanTurns(entries) {
35	  const turns = [];
36	  entries.forEach((entry, index) => {
37	    const text = humanText(entry);
38	    if (text !== null) turns.push({ index, timestamp: entry.timestamp ?? null, text });
39	  });
40	  return turns;
41	}
42	
43	// Concatenated assistant text emitted after entry `fromIndex`, up to the next
44	// owner turn (or the end of the session).
45	export function assistantTextAfter(entries, fromIndex) {
46	  const parts = [];
47	  for (let i = fromIndex + 1; i < entries.length; i += 1) {
48	    const entry = entries[i];
49	    if (humanText(entry) !== null) break;
50	    if (entry.type !== 'assistant') continue;
51	    const content = entry.message?.content;
52	    if (!Array.isArray(content)) continue;
53	    for (const block of content) {
54	      if (block?.type === 'text' && block.text) parts.push(block.text);
55	    }
56	  }
57	  return parts.join('\n');
58	}
