60	// The explicit classification line, if the reply carries one.
61	export function classificationLine(text) {
62	  const m = /^[ \t>#*_-]*comment\s+class\b[^:\n]*:(.*)$/im.exec(text || '');
63	  return m ? m[0] : null;
64	}
