66	// Canonical class tokens named on a classification line (a mixed comment may
67	// name several): 'correction' | 'feature' | 'process-change' | 'other'.
68	export function classesIn(line) {
69	  const classes = new Set();
70	  for (const m of (line || '').matchAll(/correction|feature|process[\s-]change|other/gi)) {
71	    classes.add(m[0].toLowerCase().replace(/\s+/g, '-'));
