    process.stderr.write(
      'Blocked: never delete a remote branch — a current environment bug makes the delete-push fail, so it cannot succeed. Leave the branch; it can be deleted from the GitHub UI if needed.'
    );
    process.exit(2);
  }
  process.exit(0);
});
