  try { const s = statSync(path); return [path, s.mtimeMs, s.isDirectory() ? -1 : s.size]; }
  catch { return [path, null, null]; }
}
const holds = (entries) => Array.isArray(entries) && entries.every((e) => {
  const now = stamp(e[0]);
  return now[1] === e[1] && now[2] === e[2];
