    settingsPath(projectRoot), join(corpusRoot, 'packs'), localPacksDir(projectRoot),
    ...ENGINE_INPUTS.map((rel) => join(corpusRoot, rel)),
    ...packs.flatMap((p) => [
      p.dir, join(p.dir, 'pack.mjs'), join(p.dir, 'declared-checks.json'), join(p.dir, 'skills'),
